// Queue aus dem Flow-Context holen (oder neu anlegen)
let queue = flow.get("payloadQueue") || [];

// Optional: Timestamp + ID anhängen
queue.push({
    ts: Date.now(),
    payload: msg.payload
});

// Zurück in den Flow-Context schreiben
flow.set("payloadQueue", queue);

// Optional: Queue-Länge zur Kontrolle
msg.queueLength = queue.length;

// Nachricht weiterreichen (oder return null, wenn du NICHT weiter willst)
return msg;

/**
 * Calculates the approximate size of the msg.payload object in bytes.
 * This is an approximation based on JSON stringification.
 * For more accurate byte size of the raw Sparkplug B message, you'd need
 * to intercept the raw MQTT payload before decoding.
 */

const payloadString = JSON.stringify(msg.payload);
const payloadSizeInBytes = Buffer.byteLength(payloadString, 'utf8');

// You can see this in the Node-RED debug sidebar (under the 'debug' tab)
// and in the Node-RED console log.
node.warn(`Sparkplug B Decoded Payload Size: ${payloadSizeInBytes} bytes`);

// Optionally, modify the msg.payload to include the size for further processing
// or to see it directly in the debug node.
msg.payload = {
    originalPayload: msg.payload, // Keep the original payload for context
    sizeInBytes: payloadSizeInBytes
};

return msg;

/**
 * Calculates the size of the raw Buffer payload received from MQTT.
 * This represents the actual byte size of the Sparkplug B Protobuf message
 * as it was transmitted over MQTT.
 */

if (Buffer.isBuffer(msg.payload)) {
    const rawPayloadSizeInBytes = msg.payload.length;

    // Log the size to the Node-RED debug sidebar (under the 'debug' tab)
    // and also to the Node-RED console log.
    node.warn(`Raw Sparkplug B Protobuf Payload Size: ${rawPayloadSizeInBytes} bytes`);

    // Optionally, you can attach the size to the message object
    // if you want to pass it along to another node or see it in the debug node.
    msg.rawPayloadSizeInBytes = rawPayloadSizeInBytes;

    // You can also choose to replace the payload with just the size if you only care about that:
    // msg.payload = rawPayloadSizeInBytes;

} else {
    // This should ideally not happen if the mqtt in node is configured correctly
    node.error("Error: msg.payload is not a Buffer. Check MQTT In node configuration.", msg);
}

return msg; // Pass the message along (potentially with the new property)

let last = context.get('last') || {};
let everLostAny = context.get('everLostAny') || false;

try {
    // Optional: Reset ermöglichen (falls du das brauchst, setze msg.reset = true)
    if (msg && msg.reset === true) {
        last = {};
        everLostAny = false;
        context.set('last', last);
        context.set('everLostAny', everLostAny);
        msg.payload = { ok: true, reason: "state_reset", everLostAny };
        return msg;
    }

    // Die Metric holen – wir nehmen die erste
    let metric = msg.payload && Array.isArray(msg.payload.metrics) ? msg.payload.metrics[0] : null; 
    if (!metric || typeof metric.name !== 'string') {
        msg.payload = { ok: false, error: "NoMetric", details: "payload.metrics[0] missing or invalid", everLostAny };
        return msg;
    }

    let name = metric.name;

    // Wert aus Sparkplug-Metric ziehen (fallbacks für verschiedene Typen)
    let value = (metric.hasOwnProperty('value')) ? metric.value :
                (metric.hasOwnProperty('doubleValue') ? metric.doubleValue :
                (metric.hasOwnProperty('intValue') ? metric.intValue :
                (metric.hasOwnProperty('longValue') ? metric.longValue : undefined)));

    if (typeof value !== 'number' || !isFinite(value)) {
        // Ungültiger Wert => als Fehler behandeln, everLostAny unverändert lassen
        msg.payload = { ok: false, error: "NonNumeric", metric: name, value, everLostAny };
        return msg;
    }

    // Wenn wir noch keinen alten Wert haben → nur speichern
    if (last[name] === undefined) {
        last[name] = value;
        context.set('last', last);
        context.set('everLostAny', everLostAny);
        msg.payload = { ok: true, reason: "first_value", metric: name, value, everLostAny };
        return msg;
    }

    // Vergleich: ist neuer Wert = letzter + 2?
    let expected = last[name] + 1;

    if (value === expected) {
        // OK
        msg.payload = { ok: true, metric: name, value, last: last[name], everLostAny };
    } else {
        // Packet Loss -> Flag setzen
        everLostAny = true;
        msg.payload = {
            ok: false,
            error: "PacketLoss",
            metric: name,
            value,
            last: last[name],
            expected,
            delta: value - last[name],
            everLostAny
        };
    }

    // neuen Wert speichern + Flag persistieren
    last[name] = value;
    context.set('last', last);
    context.set('everLostAny', everLostAny);

    return msg;

} catch (e) {
    msg.payload = { ok: false, error: "Exception", details: e && e.message ? e.message : String(e), everLostAny };
    return msg;
}
